@Composable internal fun PortfolioScreen(s:LensState,vm:LensViewModel,a:UiActions){
 Label("Every holding, a clearer picture",Lime);Text("Your wealth.\nIn perspective.",fontSize=35.sp,lineHeight=39.sp,color=Ink,fontWeight=FontWeight.Bold)
 var section by rememberSaveable{mutableStateOf("Overview")};ChoiceRow(listOf("Overview","Exposure","Risk","Income","Tax ledger"),section){section=it}
 val positions=s.profile().positions();val priced=positions.mapNotNull{p->s.quotes[p.symbol]?.takeIf{it.last>0}?.let{p to it}}
 val value=priced.sumOf{(p,q)->p.value(q.last)};val cost=priced.sumOf{it.first.cost()};val fundRecords=s.rows("fundValue");val fundValue=fundRecords.sumOf{Analytics.num(JSONObject(it.json),"amount").takeIf(Double::isFinite)?:0.0}
 when(section){
 "Overview"->{LensCard(accent=Lime){Label("Equities · priced holdings",Lime);Text(if(priced.isEmpty())"—"else rupees(value),color=Ink,fontSize=40.sp,fontWeight=FontWeight.Light);Text(if(priced.isEmpty())"No priced positions"else "${rupees(value-cost)}  (${percent(if(cost>0)(value/cost-1)*100 else Double.NaN,true)})",color=if(value-cost<0)Pink else Lime,fontSize=15.sp);MetricPair("Invested · all equity",rupees(positions.sumOf{it.cost()}),"Pricing coverage","${priced.size} / ${positions.size}");MetricPair("Funds · manual values",rupees(fundValue),"Equity + entered funds",if(priced.isEmpty()&&fundRecords.isEmpty())"—"else rupees(value+fundValue));Caption("Unrealized equity P&L includes fees only for priced positions. Missing quotes are excluded, never valued at zero. Fund values use your entered valuation dates.");Action(if("portfolio" in s.busy)"Refreshing…"else "Refresh portfolio",{vm.refreshPortfolio()},primary=true,enabled="portfolio" !in s.busy,icon=Icons.Rounded.Refresh)}
 ErrorLine(s,"portfolio")
 Action("Add equity holding",{a.form(newPositionForm(s,vm))},icon=Icons.Rounded.Add)
 positions.forEach{p->val q=s.quotes[p.symbol];LensCard{Text(p.symbol,color=Lime,fontSize=19.sp,fontWeight=FontWeight.Bold);MetricPair("Quantity / average",number(p.quantity,0)+" / "+rupees(p.average),"Market value",q?.let{rupees(p.value(it.last))}?:"—");MetricPair("Total cost incl. fees",rupees(p.cost()),"Unrealized P&L",q?.let{rupees(p.pnl(it.last))}?:"—");Caption(q?.let{"${it.stamp} IST · source quote"}?:"No quote available");Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Research",{a.stock(p.symbol)});Action("Edit",{a.form(positionForm(p.symbol,s,vm))});Action("Remove",{vm.task("remove:${p.symbol}"){vm.profile{it.removePosition(p.symbol)}}})}}}
 fundRecords.forEach{r->val j=JSONObject(r.json);LensCard{Text(j.optString("name"),color=Violet,fontWeight=FontWeight.SemiBold);MetricPair("Entered market value",rupees(Analytics.num(j,"amount")),"Valuation date",j.optString("date"));Action("Remove valuation",{vm.delete(r.id)})}}
 if(positions.isEmpty()&&fundRecords.isEmpty())EmptyState("Your portfolio starts here","Add shares with average cost, or add a fund valuation from Funds. Personal records stay on this phone.",Icons.Rounded.PieChart)
 }
 "Exposure"->{val direct=priced.map{(p,q)->Analytics.Exposure(q.isin.takeIf{Data.isin(it)}?:vm.repo.legacy.stock(p.symbol).isin.ifBlank{"symbol:${p.symbol}"},p.symbol,p.value(q.last),0.0)};val funds=fundRecords.map{val j=JSONObject(it.json);s.funds.firstOrNull{it.id==j.optString("fundId")} to Analytics.num(j,"amount")};val look=runCatching{Analytics.lookThrough(direct,funds)}.getOrNull()
  if(look==null)EmptyState("Inspect fund weights","One portfolio contains more than 100% recognized equity weights. Correct the disclosure before combining exposure.")
  else {LensCard(accent=Violet){Label("Look through every layer",Violet);MetricPair("Priced / entered assets",rupees(look.total),"Unmapped / non-equity fund value",rupees(look.unknown));Caption("Direct shares + entered fund value × disclosed stock weight. Fund snapshots and valuation dates can differ. Cash, debt, derivatives and unrecognized fund rows remain unmapped.");Caption("Unpriced direct positions excluded: ${positions.size-priced.size}")}
   val lookup=s.quotes.entries.associateBy{it.value.isin};val fundIndustries=s.funds.flatMap{it.holdings}.filter{it.industry.isNotBlank()}.associate{it.isin to it.industry};val sectors=look.rows.groupBy{lookup[it.isin]?.value?.industry?.ifBlank{null}?:fundIndustries[it.isin]?:"Unclassified"}.mapValues{it.value.sumOf{it.total}}.toMutableMap();if(look.unknown>0)sectors["Unmapped fund assets"]=look.unknown
   SectionTitle("Industry exposure","AMC and NSE industry labels may differ")
   LensCard{sectors.entries.sortedByDescending{it.value}.forEach{(name,v)->AllocationBar(name,v,look.total,Violet,rupees(v))}}
   SectionTitle("Company exposure","Direct + underlying fund holdings")
   look.rows.take(60).forEach{e->LensCard{AllocationBar(e.name.ifBlank{e.isin},e.total,look.total,Lime);MetricPair("Direct shares",rupees(e.direct),"Through funds",rupees(e.funds));lookup[e.isin]?.let{Action("Research",{a.stock(it.key)})}}}
  }
 }
 "Risk"->{LensCard(accent=Violet){Label("Concentration · priced equities",Violet);MetricPair("Largest holding",percent(if(value>0)priced.maxOfOrNull{it.first.value(it.second.last)}?.div(value)?.times(100)?:Double.NaN else Double.NaN),"Top 5 holdings",percent(if(value>0)priced.map{it.first.value(it.second.last)}.sortedDescending().take(5).sum()/value*100 else Double.NaN));Caption("This section uses direct equities with quotes. Fund look-through is shown under Exposure.")}
  Action("Load risk history",{priced.take(20).forEach{vm.loadHistory(it.first.symbol)}});Caption("Loads up to 20 holdings. Risk calculations use available raw prices and can be distorted by corporate actions.")
  priced.forEach{(p,q)->val history=s.histories[p.symbol].orEmpty();LensCard{Text(p.symbol,color=Ink,fontWeight=FontWeight.SemiBold);MetricPair("Max historical drawdown",percent(Analytics.drawdown(history.map{it.close})),"Annualized daily volatility",percent(Analytics.volatility(history.map{it.close})));Caption("${history.size} loaded daily closes");Action("Set target allocation",{a.form(targetForm(p.symbol,s,vm))})}}
  var shock by rememberSaveable{mutableFloatStateOf(-10f)};LensCard{Text("What if prices move?",color=Ink,fontSize=20.sp,fontWeight=FontWeight.SemiBold);Text("${number(shock.toDouble(),0)}%",color=Violet,fontSize=30.sp);Slider(shock,{shock=it},valueRange=-50f..50f,steps=19);MetricPair("Scenario equity value",if(value>0)rupees(value*(1+shock/100))else "—","Change",if(value>0)rupees(value*shock/100)else "—");Caption("Uniform price shock across priced direct equities; excludes fund values, taxes, costs and future contributions. It is an illustrative scenario.")}
  val targets=s.rows("target");if(targets.isNotEmpty()){SectionTitle("Allocation drift","Targets are your own inputs; priced equities only")
   targets.forEach{r->val j=JSONObject(r.json);val symbol=j.optString("symbol");val p=priced.firstOrNull{it.first.symbol==symbol};if(p!=null){val current=p.first.value(p.second.last);val goal=value*Analytics.num(j,"weight")/100;val delta=goal-current;LensCard{Text(symbol,color=Ink,fontWeight=FontWeight.Bold);MetricPair("Current allocation",percent(current/value*100),"Target",percent(Analytics.num(j,"weight")));MetricPair("Value difference",rupees(delta),"Whole-share magnitude",number(floor(abs(delta)/p.second.last),0));Caption("Positive value difference means below your target. Execution prices, liquidity, fees and tax can change the outcome. Use the tax sale preview for acquisition-lot effects.");Action("Edit target",{a.form(targetForm(symbol,s,vm))});Action("Remove target",{vm.delete(r.id)})}}}
  }
 }
 "Income"->IncomeScreen(s,vm,a)
 else->TaxScreen(s,vm,a)
 }
}
internal fun newPositionForm(s:LensState,vm:LensViewModel)=FormSpec("Add equity holding","An average-cost position is separate from the dated tax transaction ledger.",listOf(FormField("symbol","NSE symbol"),FormField("quantity","Whole shares",number=true),FormField("average","Average purchase price (₹)",number=true),FormField("fees","Total acquisition fees (₹)","0",number=true))){v->savePosition(v.getValue("symbol").uppercase(),v,vm)}
internal fun positionForm(symbol:String,s:LensState,vm:LensViewModel):FormSpec{val p=s.profile().positions().firstOrNull{it.symbol==symbol};return FormSpec("$symbol · equity holding","Manual average-cost position. Tax records use separate dated acquisition/sale lots.",listOf(FormField("quantity","Whole shares",p?.quantity?.toString()?:"",number=true),FormField("average","Average purchase price (₹)",p?.average?.toString()?:"",number=true),FormField("fees","Total acquisition fees (₹)",p?.fees?.toString()?:"0",number=true))){v->savePosition(symbol,v,vm)}}
private suspend fun savePosition(symbol:String,v:Map<String,String>,vm:LensViewModel){require(Data.validSymbol(symbol));val p=Research.Position();p.symbol=symbol;p.name=vm.repo.legacy.stock(symbol).name;p.quantity=v.getValue("quantity").toDouble();p.average=v.getValue("average").toDouble();p.fees=v.getValue("fees").toDouble();vm.profile{it.position(p)}}
internal fun alertForm(symbol:String,s:LensState,vm:LensViewModel):FormSpec {
 val old=s.profile().alert(symbol);val relative=s.profile().data.optJSONObject("relativeAlerts")?.optJSONObject(symbol)
 return FormSpec("$symbol · price alerts","Choose absolute prices, returns relative to your current average acquisition cost including fees, or both. Relative alerts require a saved equity position. Enable background checks in Settings.",listOf(FormField("below","At / below price (₹)",old?.optString("below")?:"",number=true),FormField("above","At / above price (₹)",old?.optString("above")?:"",number=true),FormField("returnBelow","Return at / below (%)",relative?.optString("below")?:"",number=true,helper="For example -10 means 10% below your cost."),FormField("returnAbove","Return at / above (%)",relative?.optString("above")?:"",number=true))){v->
  fun parse(key:String):Double {val text=v.getValue(key);if(text.isBlank())return Double.NaN;return text.toDouble().also{require(it.isFinite())}}
  val below=parse("below");val above=parse("above");val lower=parse("returnBelow");val upper=parse("returnAbove")
  require(listOf(below,above,lower,upper).any{it.isFinite()}){"Enter at least one threshold"}
  if(lower.isFinite()&&upper.isFinite())require(lower<upper){"Lower return must be below upper return"}
  if(lower.isFinite()||upper.isFinite())require(s.profile().positions().any{it.symbol==symbol&&it.cost()>0}){"Add a position with positive acquisition cost first"}
  vm.profile{state->if(below.isFinite()||above.isFinite())state.alert(symbol,below,above)else state.removeAlert(symbol);if(lower.isFinite()||upper.isFinite()){val j=JSONObject();if(lower.isFinite())j.put("below",lower);if(upper.isFinite())j.put("above",upper);state.section("relativeAlerts").put(symbol,j)}else state.section("relativeAlerts").remove(symbol)}
 }
}
private fun targetForm(symbol:String,s:LensState,vm:LensViewModel)=FormSpec("$symbol · allocation target",fields=listOf(FormField("weight","Target % of priced direct equities",s.json("target:$symbol").optString("weight"),number=true))){v->val w=v.getValue("weight").toDouble();require(w.isFinite()&&w in 0.0..100.0);val other=s.rows("target").filter{it.id!="target:$symbol"}.sumOf{Analytics.num(JSONObject(it.json),"weight")};require(other+w<=100.0001){"Total targets exceed 100%"};vm.save("target","target:$symbol",JSONObject().put("symbol",symbol).put("weight",w))}

@Composable private fun IncomeScreen(s:LensState,vm:LensViewModel,a:UiActions){
 val rows=s.rows("dividend");val js=rows.map{JSONObject(it.json)};LensCard(accent=Lime){Label("Dividend income",Lime);MetricPair("Expected gross",rupees(js.sumOf{Analytics.num(it,"expected")}),"Received net",rupees(js.sumOf{Analytics.num(it,"received")}));MetricPair("Recorded withholding / TDS",rupees(js.sumOf{Analytics.num(it,"tds")}),"Unreconciled gross",rupees(js.sumOf{Analytics.num(it,"expected")-Analytics.num(it,"received")-Analytics.num(it,"tds")}));Caption("Manual records. Expected dividends require your eligible quantity; today's holding does not prove entitlement.")}
 Action("Record expected / received dividend",{a.form(dividendForm(vm))},primary=true,icon=Icons.Rounded.Add)
 if(rows.isEmpty())EmptyState("Track the income too","Record entitlement dates, expected amounts, receipts and withholding, then reconcile with bank records.",Icons.Rounded.Payments)
 rows.sortedBy{JSONObject(it.json).optString("payment")}.forEach{r->val j=JSONObject(r.json);LensCard{Label(j.optString("symbol"),Lime);MetricPair("Expected gross",rupees(Analytics.num(j,"expected")),"Received net",rupees(Analytics.num(j,"received")));MetricPair("Withholding / TDS",rupees(Analytics.num(j,"tds")),"Difference",rupees(Analytics.num(j,"expected")-Analytics.num(j,"received")-Analytics.num(j,"tds")));Caption("Ex ${dateText(j.optString("ex"))} · record ${dateText(j.optString("record"))}\nPayment ${dateText(j.optString("payment"))} · received ${dateText(j.optString("receivedDate"))}");Caption(j.optString("note"));if(j.optString("source").isNotBlank())Action("Original disclosure",{a.url(j.optString("source"))});Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Edit / reconcile",{a.form(dividendForm(vm,r))});Action("Delete",{vm.delete(r.id)})}}}
 if(rows.isNotEmpty())Action("Export dividend records",{val fields=listOf("symbol","ex","record","payment","receivedDate","expected","received","tds","source","note");a.export("MarketLens-dividends.csv",fields.joinToString(",")+"\n"+js.joinToString("\n"){j->fields.joinToString(","){csvCell(j.optString(it))}},"text/csv")},icon=Icons.Rounded.Download)
}
private fun dividendForm(vm:LensViewModel,row:LocalRecord?=null):FormSpec{val j=row?.let{JSONObject(it.json)}?:JSONObject();return FormSpec("Dividend record","Enter gross expected, net received and withholding separately. Dates are YYYY-MM-DD; unknown dates can stay blank.",listOf(FormField("symbol","NSE symbol",j.optString("symbol")))+listOf("ex" to "Ex-dividend date","record" to "Record date","payment" to "Expected payment date","receivedDate" to "Actual receipt date").map{FormField(it.first,it.second,j.optString(it.first))}+listOf("expected" to "Expected gross (₹)","received" to "Received net (₹)","tds" to "Withholding / TDS (₹)").map{FormField(it.first,it.second,j.optString(it.first,"0"),number=true)}+listOf(FormField("source","Original HTTPS source (optional)",j.optString("source")),FormField("note","Account / reconciliation note",j.optString("note"),multiline=true))){v->val out=JSONObject();v.forEach{(k,x)->when(k){"expected","received","tds"->{val n=x.toDouble();require(n.isFinite()&&n>=0);out.put(k,n)};"ex","record","payment","receivedDate"->{if(x.isNotBlank())LocalDate.parse(x);out.put(k,x)};else->out.put(k,x)}};out.put("symbol",v.getValue("symbol").uppercase());require(Data.validSymbol(out.getString("symbol")));require(v.getValue("source").isBlank()||safeUrl(v.getValue("source")));vm.save("dividend",row?.id?:java.util.UUID.randomUUID().toString(),out)}}
internal fun csvCell(raw:String):String {val safe=if(raw.startsWith("=")||raw.startsWith("+")||raw.startsWith("-")||raw.startsWith("@"))"'$raw"else raw;return "\""+safe.replace("\"","\"\"")+"\""}

@Composable private fun TaxScreen(s:LensState,vm:LensViewModel,a:UiActions){
 val trades=runCatching{Analytics.trades(s.records)}.getOrDefault(emptyList());val ledger=runCatching{Analytics.fifo(trades)}.getOrNull();var fy by rememberSaveable{mutableStateOf("All years")};val years=(ledger?.disposals?.map{Analytics.fy(it.sold)}.orEmpty()+Analytics.fy(LocalDate.now().toString())).distinct().sortedDescending();ChoiceRow(listOf("All years")+years,fy){fy=it};val disposals=ledger?.disposals.orEmpty().filter{fy=="All years"||Analytics.fy(it.sold)==fy}
 LensCard(accent=Violet){Label("FIFO acquisition-lot report",Violet);MetricPair("Net realized gains",rupees(disposals.sumOf{it.gain}),"Matched disposal lots",disposals.size.toString());Caption("Independent dated transaction ledger, grouped by account and symbol. Includes entered acquisition and sale fees. Average-cost portfolio positions are not opening tax lots. Corporate actions and missing acquisition history must be corrected before relying on this report.");Caption("No statutory tax rates, exemptions or grandfathering are assumed. Export lot dates and costs for review.")}
 Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Action("Add transaction",{a.form(tradeForm(vm))},primary=true,icon=Icons.Rounded.Add);Action("Import CSV",{a.importFile("trades")},icon=Icons.Rounded.UploadFile)}
 Action("Download import template",{a.export("MarketLens-transactions-template.csv","id,date,symbol,side,quantity,price,fees,account\n","text/csv")});Caption("BUY/SELL CSV; fees are totals per transaction. Use unique IDs to preserve genuinely identical trades. Reimports with an existing ID are skipped.")
 if(trades.isEmpty())EmptyState("Start with the acquisition lots","Add your complete dated purchases before sales. An oversold account/symbol is rejected.",Icons.Rounded.ReceiptLong)
 trades.sortedWith(compareByDescending<Analytics.Trade>{it.date}.thenByDescending{it.id}).take(50).forEach{t->LensCard{Label("${t.side} · ${t.symbol}",if(t.side=="BUY")Lime else Pink);Text("${number(t.quantity,0)} shares × ${rupees(t.price)}",color=Ink,fontWeight=FontWeight.SemiBold);Caption("${t.account} · ${t.date} · fees ${rupees(t.fees)}");Action("Delete transaction",{vm.delete(t.id)});ErrorLine(s,"delete:${t.id}")}}
 if(disposals.isNotEmpty()){SectionTitle("Realized acquisition lots");disposals.take(50).forEach{d->LensCard{Text("${d.symbol} · ${d.account}",color=Ink,fontWeight=FontWeight.SemiBold);MetricPair("Quantity",number(d.quantity,0),"Net gain",rupees(d.gain));MetricPair("Cost incl. fees",rupees(d.cost),"Net proceeds",rupees(d.proceeds));Caption("Bought ${d.acquired} · sold ${d.sold} · ${d.days} days held")}}
  Action("Export financial-year lot report",{val head="account,symbol,acquired,sold,quantity,cost,net_proceeds,net_gain,days_held\n";val body=disposals.joinToString("\n"){d->listOf(d.account,d.symbol,d.acquired,d.sold,d.quantity.toString(),d.cost.toString(),d.proceeds.toString(),d.gain.toString(),d.days.toString()).joinToString(","){csvCell(it)}};a.export("MarketLens-FIFO-$fy.csv",head+body,"text/csv")},icon=Icons.Rounded.Download)
 }
 if(ledger!=null&&ledger.open.isNotEmpty())Action("Preview a proposed sale",{a.form(salePreviewForm(trades,vm))},icon=Icons.Rounded.Calculate)
 val preview=s.json("salePreview");if(preview.has("gain"))LensCard(accent=Violet){Label("Illustrative sale preview",Violet);Caption(preview.optString("description"));MetricPair("Estimated net gain",rupees(Analytics.num(preview,"gain")),"User-rate estimate",rupees(Analytics.num(preview,"tax")));Caption("Uses the rates and holding-period cutoff you entered. Taxes apply only to positive individual lot gains in this illustration; excludes loss offsets, exemptions, surcharge, cess, grandfathering and other adjustments. It does not record a sale.")}
}
private fun tradeForm(vm:LensViewModel)=FormSpec("Dated equity transaction","Add acquisition lots before sales. Same-day trades use import/save order; use distinct IDs in CSV when that order matters.",listOf(FormField("account","Account nickname","Personal"),FormField("symbol","NSE symbol"),FormField("date","Trade date · YYYY-MM-DD",LocalDate.now().toString()),FormField("side","Side","BUY",listOf("BUY","SELL")),FormField("quantity","Whole shares",number=true),FormField("price","Price per share (₹)",number=true),FormField("fees","Total transaction fees (₹)","0",number=true))){v->val j=JSONObject();v.forEach{(k,x)->if(k in listOf("quantity","price","fees")){val n=x.toDouble();require(n.isFinite());if(k=="quantity")require(n==floor(n));j.put(k,n)}else j.put(k,if(k=="symbol")x.uppercase()else x)};require(!LocalDate.parse(v.getValue("date")).isAfter(LocalDate.now())){"Future transactions cannot be booked"};vm.repo.saveTrade("trade:"+System.currentTimeMillis().toString()+":"+java.util.UUID.randomUUID().toString(),j)}
private fun salePreviewForm(trades:List<Analytics.Trade>,vm:LensViewModel)=FormSpec("Proposed sale preview","Supply your own tax assumptions. The calculation is illustrative and does not place an order.",listOf(FormField("account","Account nickname","Personal"),FormField("symbol","NSE symbol"),FormField("quantity","Whole shares to sell",number=true),FormField("price","Assumed sale price (₹)",number=true),FormField("fees","Total sale fees (₹)","0",number=true),FormField("cutoff","Your long-holding cutoff in days",number=true),FormField("shortRate","Your short-holding rate (%)",number=true),FormField("longRate","Your long-holding rate (%)",number=true))){v->val qty=v.getValue("quantity").toDouble();require(qty==floor(qty));val price=v.getValue("price").toDouble();val fees=v.getValue("fees").toDouble();val cutoff=v.getValue("cutoff").toLong();require(cutoff>=0);val short=v.getValue("shortRate").toDouble();val long=v.getValue("longRate").toDouble();require(short.isFinite()&&long.isFinite()&&short in 0.0..100.0&&long in 0.0..100.0);val t=Analytics.Trade("zz-preview",v.getValue("account"),v.getValue("symbol").uppercase(),LocalDate.now().toString(),"SELL",qty,price,fees,Long.MAX_VALUE);val before=Analytics.fifo(trades).disposals.size;val lots=Analytics.fifo(trades+t).disposals.drop(before);vm.save("preview","salePreview",JSONObject().put("description","${t.symbol} · ${t.account} · $qty shares at ${rupees(price)} · cutoff $cutoff days · rates $short% / $long%").put("gain",lots.sumOf{it.gain}).put("tax",lots.sumOf{max(0.0,it.gain)*(if(it.days>cutoff)long else short)/100}))}
